class Solution { fun maxProfit(k: Int, p: IntArray): Int { val n = p.size; if (n == 0 || k == 0) return 0; if (k >= n / 2) { var ans = 0; for (i in 1 until n) ans += maxOf(p[i] - p[i - 1], 0); return ans }; val buy = IntArray(k + 1) { Int.MAX_VALUE }; val sell = IntArray(k + 1); for (price in p) for (t in 1..k) { buy[t] = minOf(buy[t], price - sell[t - 1]); sell[t] = maxOf(sell[t], price - buy[t]) }; return sell[k] } }
